import{_ as t}from"./chunks/capture-picker.DtS6chX6.js";import{_ as a,o,c as r,a2 as s}from"./chunks/framework.CfwCq2QB.js";const m=JSON.parse('{"title":"Page export (PDF / image)","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/capture.md","filePath":"en/features/capture.md"}'),n={name:"en/features/capture.md"};function i(l,e,p,d,h,c){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="page-export-pdf-image" tabindex="-1">Page export (PDF / image) <a class="header-anchor" href="#page-export-pdf-image" aria-label="Permalink to &quot;Page export (PDF / image)&quot;">​</a></h1><p>In one line: export the current page as a PDF or long image that looks exactly like it does on screen — styles and images intact — or pick one part of the page and export just that.</p><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to &quot;Using it&quot;">​</a></h2><p>Open the page, click the toolbar icon to open the popup, switch to the Features tab, and find &quot;Export page&quot;:</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Page PDF</strong></td><td>Scrolls through the whole page and stitches it into a PDF. Text in the PDF can be selected, copied and searched</td></tr><tr><td><strong>Page image</strong></td><td>Captures the whole page the same way and saves it as one long PNG</td></tr><tr><td><strong>Select area</strong></td><td>The popup closes; pick a block on the page (a card, a table, a section) and export it as an image or PDF — see below</td></tr></tbody></table><p>Files go straight to the browser&#39;s download folder, and the popup shows the file name. The page&#39;s right-click menu also has &quot;Export page as PDF&quot; and &quot;Export a page area as image / PDF&quot;.</p><h2 id="exporting-a-selected-area" tabindex="-1">Exporting a selected area <a class="header-anchor" href="#exporting-a-selected-area" aria-label="Permalink to &quot;Exporting a selected area&quot;">​</a></h2><p>After clicking &quot;Select area&quot;:</p><ol><li>Move the mouse over the page — a blue box highlights the element under the cursor and shows its size</li><li>Picked too small or too large? Press <strong>↑</strong> for the parent element and <strong>↓</strong> to go back to the child</li><li>Click to lock it and a toolbar appears: <strong>Export image</strong> / <strong>Export PDF</strong> / <strong>Pick again</strong> / <strong>Cancel</strong>; <strong>Esc</strong> exits at any time</li></ol><p>You get the element&#39;s <strong>full content</strong>, not just the part visible on screen: elements taller than the window are scrolled through in segments and stitched together.</p><img src="'+t+'" alt="Selecting an area to export: a card on the page outlined in blue, with an Export image / Export PDF / Pick again / Cancel toolbar above it (Chinese UI)"><p><em>Selecting an area: once the card is locked, the export toolbar appears (screenshot shows the Chinese UI).</em></p><h2 id="how-is-this-different-from-print-to-pdf" tabindex="-1">How is this different from &quot;Print to PDF&quot;? <a class="header-anchor" href="#how-is-this-different-from-print-to-pdf" aria-label="Permalink to &quot;How is this different from &quot;Print to PDF&quot;?&quot;">​</a></h2><p>The browser&#39;s print dialog re-lays the page out for paper, often dropping backgrounds, shifting elements, or splitting the page awkwardly. DevGo captures the page exactly as it&#39;s rendered on screen:</p><ul><li>Background colors, gradients, images, rounded corners and shadows are kept</li><li>Sticky headers and floating buttons appear only once, at the top, instead of repeating on every segment</li><li>DevGo&#39;s own UI (the dock, the selection toolbar) never shows up in the export</li><li>Full-page PDFs carry an invisible text layer, so text can be selected, copied and searched</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Browser built-in pages (<code>chrome://</code> URLs) and the extension store don&#39;t allow screenshots; the buttons say the page isn&#39;t supported</li><li>Very long pages take a few seconds to a few tens of seconds while the page scrolls automatically — stay on the tab until it finishes</li><li>Infinite-scroll feeds can only be exported as far as they&#39;ve loaded</li><li>No extra permissions are required</li></ul>',17)])])}const f=a(n,[["render",i]]);export{m as __pageData,f as default};
